<?php
$error=null;$role=role_name();$patient=patient_for_current_user();$doctor=doctor_for_current_user();$committed=false;
if(request_method('POST')){require_roles(['Admin','Lab Operator']);try{verify_csrf();$itemId=(int)($_POST['request_item_id']??0);$status=post_string('status');$allowed=['Requested','Sample Collected','Processing','Completed','Cancelled'];if(!in_array($status,$allowed,true))throw new RuntimeException('Invalid laboratory status.');$stmt=db()->prepare('SELECT lri.*,lr.lab_request_id,lr.patient_id FROM lab_request_items lri JOIN lab_requests lr ON lr.lab_request_id=lri.lab_request_id WHERE lri.request_item_id=?');$stmt->execute([$itemId]);$item=$stmt->fetch();if(!$item)throw new RuntimeException('Laboratory item not found.');$file=uploaded_file('report_file','lab_reports');$sample=in_array($status,['Sample Collected','Processing','Completed'],true)&&!$item['sample_collected_at']?date('Y-m-d H:i:s'):$item['sample_collected_at'];$completed=$status==='Completed'?date('Y-m-d H:i:s'):null;$path=$file?:$item['report_file_path'];if($status==='Completed'&&post_string('result_summary')===''&&post_string('result_value')===''&&!$path)throw new RuntimeException('Enter a result summary/value or upload a report before completing the test.');$pdo=db();$pdo->beginTransaction();$pdo->prepare('UPDATE lab_request_items SET status=?,result_summary=?,result_value=?,report_file_path=?,sample_collected_at=?,completed_at=?,processed_by=? WHERE request_item_id=?')->execute([$status,nullable(post_string('result_summary')),nullable(post_string('result_value')),$path,$sample,$completed,current_user()['user_id'],$itemId]);$statusStmt=db()->prepare("SELECT status,COUNT(*) total FROM lab_request_items WHERE lab_request_id=? GROUP BY status");$statusStmt->execute([$item['lab_request_id']]);$statusCounts=[];foreach($statusStmt->fetchAll() as $statusRow)$statusCounts[$statusRow['status']]=(int)$statusRow['total'];$totalItems=array_sum($statusCounts);$completedItems=$statusCounts['Completed']??0;$cancelledItems=$statusCounts['Cancelled']??0;$inProgressItems=($statusCounts['Sample Collected']??0)+($statusCounts['Processing']??0);if($totalItems>0&&$cancelledItems===$totalItems)$requestStatus='Cancelled';elseif($totalItems>0&&$completedItems+$cancelledItems===$totalItems)$requestStatus='Completed';elseif($inProgressItems>0||$completedItems>0)$requestStatus='Processing';else $requestStatus='Requested';$pdo->prepare('UPDATE lab_requests SET status=? WHERE lab_request_id=?')->execute([$requestStatus,$item['lab_request_id']]);$pdo->commit();$committed=true;if($status==='Completed')notify_user(find_patient_user_id((int)$item['patient_id']),'Lab report available','A laboratory result has been completed and is ready to view.','Lab','labs',(int)$item['lab_request_id']);log_action('UPDATE_LAB_ITEM','lab_request_items',$itemId,$item,['status'=>$status]);flash('lab','Laboratory item updated.','success');redirect_to('labs',['edit'=>$itemId]);}catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();if(!$committed&&!empty($file)&&is_file(ROOT_PATH.'/'.ltrim((string)$file,'/')))@unlink(ROOT_PATH.'/'.ltrim((string)$file,'/'));$error=$e->getMessage();}}
$where=[];$params=[];if($role==='Patient'){$where[]='lr.patient_id=?';$params[]=$patient['patient_id'];}elseif($role==='Doctor'){$where[]='lr.doctor_id=?';$params[]=$doctor['doctor_id'];}if(get_string('status')!==''){$where[]='lri.status=?';$params[]=get_string('status');}$sql="SELECT lri.*,lr.request_number,lr.priority,lr.requested_at,lr.patient_id,p.patient_code,p.full_name patient_name,lt.test_code,lt.test_name,lt.normal_range,u.full_name doctor_name FROM lab_request_items lri JOIN lab_requests lr ON lr.lab_request_id=lri.lab_request_id JOIN patients p ON p.patient_id=lr.patient_id JOIN lab_tests lt ON lt.lab_test_id=lri.lab_test_id JOIN doctors d ON d.doctor_id=lr.doctor_id JOIN users u ON u.user_id=d.user_id".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY FIELD(lri.status,'Requested','Sample Collected','Processing','Completed','Cancelled'),lr.requested_at DESC LIMIT 250";$stmt=db()->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$edit=null;if(isset($_GET['edit'])&&has_role(['Admin','Lab Operator'])){foreach($rows as $r)if((int)$r['request_item_id']===(int)$_GET['edit']){$edit=$r;break;}}
?>
<div class="page-header"><div><h2>Laboratory</h2><p>Requests, sample progress, result summaries and report files.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="grid grid-4 mb-2"><?php foreach([['Requested','#2563eb'],['Sample Collected','#0f766e'],['Processing','#d97706'],['Completed','#15803d']] as $s):?><div class="card stat-card" style="--stat-color:<?=$s[1]?>"><div><div class="stat-label"><?=$s[0]?></div><div class="stat-value"><?=count(array_filter($rows,fn($r)=>$r['status']===$s[0]))?></div><div class="stat-note">Visible work items</div></div><div class="stat-icon">⚗</div></div><?php endforeach;?></div><div class="card mb-2"><form method="get" class="actions"><input type="hidden" name="page" value="labs"><select class="select" style="max-width:230px" name="status"><option value="">All statuses</option><?php foreach(['Requested','Sample Collected','Processing','Completed','Cancelled'] as $s):?><option <?=get_string('status')===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-light">Filter</button></form></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Request</th><th>Patient</th><th>Test</th><th>Doctor</th><th>Priority</th><th>Status</th><th>Result</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><div class="table-title"><?=e($r['request_number'])?></div><div class="table-subtitle"><?=format_date($r['requested_at'],'d M Y, h:i A')?></div></td><td><?=e($r['patient_name'])?><div class="table-subtitle"><?=e($r['patient_code'])?></div></td><td><?=e($r['test_name'])?><div class="table-subtitle"><?=e($r['test_code'])?></div></td><td><?=e($r['doctor_name'])?></td><td><?=e($r['priority'])?></td><td><span class="badge badge-<?=status_class($r['status'])?>"><?=e($r['status'])?></span></td><td><?=e($r['result_value']??'—')?><div class="table-subtitle"><?=e($r['result_summary']??'')?></div></td><td><?php if(has_role(['Admin','Lab Operator'])):?><a class="btn btn-primary btn-sm" href="<?=e(route_url('labs',['edit'=>$r['request_item_id']]))?>">Process</a><?php endif;?><?php if($r['report_file_path']):?><a class="btn btn-light btn-sm" target="_blank" href="<?=e(url('download.php?type=lab&id='.$r['request_item_id']))?>">Report</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty-state"><p>No laboratory items found.</p></div><?php endif;?></div>
<?php if($edit):?><div class="modal-backdrop open" id="labModal"><div class="modal"><div class="modal-header"><h3>Process <?=e($edit['test_name'])?></h3><a class="close-btn" href="<?=e(route_url('labs'))?>">×</a></div><form method="post" enctype="multipart/form-data"><div class="modal-body"><?=csrf_field()?><input type="hidden" name="request_item_id" value="<?=$edit['request_item_id']?>"><div class="alert alert-info"><div><strong><?=e($edit['patient_name'])?></strong><br><?=e($edit['request_number'])?> · <?=e($edit['priority'])?> priority</div></div><div class="field"><label>Status</label><select class="select" name="status"><?php foreach(['Requested','Sample Collected','Processing','Completed','Cancelled'] as $s):?><option <?=$edit['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div><div class="form-grid"><div class="field"><label>Result value</label><input class="input" name="result_value" value="<?=e($edit['result_value']??'')?>"></div><div class="field"><label>Normal range</label><input class="input" value="<?=e($edit['normal_range']??'')?>" disabled></div></div><div class="field"><label>Result summary</label><textarea class="textarea" name="result_summary"><?=e($edit['result_summary']??'')?></textarea></div><div class="field"><label>Report file</label><input class="input" type="file" name="report_file" accept=".pdf,.jpg,.jpeg,.png"><div class="help">PDF, JPG or PNG; maximum 5 MB.</div></div></div><div class="modal-footer"><a class="btn btn-light" href="<?=e(route_url('labs'))?>">Cancel</a><button class="btn btn-primary">Save result</button></div></form></div></div><?php endif;?>
